const text=String($input.item.json.input??'').toLowerCase();
const flags=['severe chest pain','crushing chest pain','pressure in chest',"can't breathe",'cannot breathe',
'difficulty breathing','severe shortness of breath','unconscious','passed out','not responding','suicidal',
'kill myself','want to die','self harm','self-harm','heavy bleeding','uncontrolled bleeding','vomiting blood',
