const text = ($input.item.json.input || '').toLowerCase();
const rules = [
  { keywords: ['fever','headache','cold','flu','cough','sore throat','body ache','tired','fatigue'], department: 'General Medicine' },
  { keywords: ['chest pain','heart','palpitation','blood pressure','breathless'], department: 'Cardiology' },
  { keywords: ['skin','rash','acne','itch','allergy'], department: 'Dermatology' },
  { keywords: ['child','kid','infant','baby','toddler'], department: 'Pediatrics' },
  { keywords: ['bone','joint','fracture','back pain','knee','sprain'], department: 'Orthopedics' },
  { keywords: ['ear','nose','throat','sinus','hearing'], department: 'ENT' },
  { keywords: ['migraine','seizure','nerve','dizziness','numbness'], department: 'Neurology' }
];
let department = 'General Medicine';
let matchedKeyword = null;
for (const rule of rules) {
  const hit = rule.keywords.find(function (k) { return text.indexOf(k) !== -1; });
  if (hit) { department = rule.department; matchedKeyword = hit; break; }
}
const reason = matchedKeyword ? ('Symptom "' + matchedKeyword + '" is commonly handled by ' + department + '.') : 'No specific symptom keyword matched; defaulting to General Medicine for initial assessment.';
return 'Department: ' + department + '\nReason: ' + reason;

let x = $input.item.json.query ?? $input.item.json;
if (typeof x === 'string') { try { x = JSON.parse(x); } catch (e) { x = {}; } }
x = x || {};
return JSON.stringify({
  doctorName: x.doctorName || '',
  preferredDate: x.preferredDate || '',
  availableSlots: ['09:00 AM','10:00 AM','11:00 AM','02:00 PM','03:00 PM','04:00 PM'],
  note: 'Mock availability returned by this single-workflow demo. These are illustrative slots, not real Google Calendar free/busy data.'
});

const body = $json.body ?? $json;
const chatInput = body.chatInput ?? body.input ?? body.message ?? '';
const sessionId = body.sessionId ?? body.session_id ?? 'webhook-' + Date.now();
return [{ json: { chatInput, sessionId } }];
